<?php
require_once __DIR__.'/../includes/init.php';require_role('petugas');require_once __DIR__.'/../includes/layout.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id||$id<1){http_response_code(404);require __DIR__.'/../includes/404.php';exit;}
$s=db()->prepare('SELECT t.*,k.plat_nomor,k.jenis_kendaraan,k.warna,k.pemilik,a.nama_area,u.nama_lengkap AS nama_petugas,c.kode_kartu FROM tb_transaksi t JOIN tb_kendaraan k ON k.id_kendaraan=t.id_kendaraan JOIN tb_area_parkir a ON a.id_area=t.id_area JOIN tb_user u ON u.id_user=t.id_user LEFT JOIN tb_kartu_parkir c ON c.id_kartu=t.id_kartu WHERE t.id_parkir=? AND (t.id_user=? OR t.id_user_keluar=?)');$s->execute([$id,current_user()['id'],current_user()['id']]);$r=$s->fetch();if(!$r||$r['status']!=='keluar'){http_response_code(404);require __DIR__.'/../includes/404.php';exit;}
render_header('Struk Parkir','riwayat');?>
