<div style="padding:10px 0"><div class="receipt-line"><span>Plat nomor</span><strong><?= h($r['plat_nomor']) ?></strong></div><div class="receipt-line"><span>Jenis kendaraan</span><strong><?= h(ucfirst($r['jenis_kendaraan'])) ?></strong></div><div class="receipt-line"><span>Warna / pemilik</span><strong><?= h($r['warna'].' / '.$r['pemilik']) ?></strong></div><div class="receipt-line"><span>Area parkir</span><strong><?= h($r['nama_area']) ?></strong></div><div class="receipt-line"><span>Waktu masuk</span><strong><?= h(tanggal($r['waktu_masuk'])) ?></strong></div><div class="receipt-line"><span>Waktu keluar</span><strong><?= h(tanggal($r['waktu_keluar'])) ?></strong></div><div class="receipt-line"><span>Durasi parkir</span><strong><?= (int)$r['durasi_jam'] ?> jam</strong></div><div class="receipt-line"><span>Tarif per jam</span><strong><?= h(rupiah($r['tarif_saat_masuk'])) ?></strong></div><div class="receipt-line"><span>Metode pembayaran</span><strong><?= strtoupper(h($r['metode_pembayaran']??'tunai')) ?></strong></div><div class="receipt-line"><span>Status pembayaran</span><strong><?= h(str_replace('_',' ',ucfirst($r['status_pembayaran']??'lunas'))) ?></strong></div><div class="receipt-line" style="align-items:center;padding-top:17px"><span><strong>Total biaya</strong></span><strong class="receipt-total"><?= h(rupiah($r['biaya_total'])) ?></strong></div></div>
<?php if(($r['metode_pembayaran']??'tunai')==='qris' && ($r['status_pembayaran']??'')!=='lunas'): ?><div class="panel-body no-print" style="padding:14px 0"><div class="alert alert-error">Pembayaran QRIS belum terverifikasi. Jangan gunakan gambar QRIS statis atau screenshot sebagai bukti pembayaran. Gunakan QR dinamis yang dibuat untuk transaksi ini melalui Midtrans.</div><a class="btn btn-primary" href="<?= h(url('petugas/pembayaran.php?transaction='.(int)$r['id_parkir'])) ?>">Buka pembayaran QRIS transaksi ini</a><p class="muted" style="margin-top:10px">Status lunas hanya ditetapkan setelah status transaksi diverifikasi langsung ke Midtrans atau melalui webhook dengan signature yang sah.</p></div><?php endif; ?>
